-- ── hand-written: what may happen to a return ───────────────────────────────────────────────────
-- The guard of a return, whoever writes the row, the functions below included. A return starts
-- as a draft; once posted it is never changed, and only a draft is removed. It is for one
-- posted goods received note: its supplier, its warehouse and that warehouse's branch are the
-- note's, and never change. The times on a row are the database's own. Only a session signed
-- in as postgres itself (a migration, or the removal of a synthetic test company) is not held
-- to this.
CREATE FUNCTION app.check_supplier_return() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_scope uuid[] := app.tenant_branch_ids();
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD.tenant_id IS DISTINCT FROM app.tenant_id() THEN
      RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'a posted return is never removed' USING ERRCODE = 'SE248';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.tenant_id IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NOT isfinite(NEW.return_date) THEN
    RAISE EXCEPTION 'the date of a return is a day on the calendar' USING ERRCODE = 'SE252';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'a return starts as a draft' USING ERRCODE = 'SE247';
    END IF;
    NEW.created_at := now();
    NEW.updated_at := clock_timestamp();
    -- This guard runs before the policies do. So the goods received note is looked for only on
    -- behalf of a member who may write a return in the branch the row names; anyone else is
    -- left to the policies, which refuse them in the same words whether the note is there or not.
    IF app.tenant_role() IN ('owner', 'accountant') AND (v_scope IS NULL OR NEW.branch_id = ANY (v_scope)) AND NOT EXISTS (
      SELECT 1 FROM public.goods_receipts r
      JOIN public.warehouses w ON w.tenant_id = r.tenant_id AND w.id = r.warehouse_id
      WHERE r.tenant_id = NEW.tenant_id AND r.id = NEW.receipt_id AND r.status = 'posted'
        AND r.supplier_id = NEW.supplier_id AND r.warehouse_id = NEW.warehouse_id AND w.branch_id = NEW.branch_id
    ) THEN
      RAISE EXCEPTION 'goods are sent back against a posted goods received note, to its supplier, out of its warehouse' USING ERRCODE = 'SE254';
    END IF;
  ELSE
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'a posted return is never changed' USING ERRCODE = 'SE248';
    END IF;
    IF NEW.id <> OLD.id OR NEW.tenant_id <> OLD.tenant_id OR NEW.created_by <> OLD.created_by OR NEW.created_at <> OLD.created_at THEN
      RAISE EXCEPTION 'what a return is and who wrote it never change' USING ERRCODE = 'SE248';
    END IF;
    IF NEW.receipt_id <> OLD.receipt_id OR NEW.supplier_id <> OLD.supplier_id OR NEW.warehouse_id <> OLD.warehouse_id OR NEW.branch_id <> OLD.branch_id THEN
      RAISE EXCEPTION 'a return stays with the goods received note it was written for' USING ERRCODE = 'SE254';
    END IF;
    -- Always later than what anyone read before this change, so a screen opened earlier can tell.
    NEW.updated_at := clock_timestamp();
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_supplier_return() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER supplier_returns_check
  BEFORE INSERT OR UPDATE OR DELETE ON public.supplier_returns
  FOR EACH ROW EXECUTE FUNCTION app.check_supplier_return();
--> statement-breakpoint
ALTER TABLE public.supplier_returns ENABLE ALWAYS TRIGGER supplier_returns_check;
