-- A line is written or removed only while its return is a draft. The return's row is held
-- until the transaction ends, so a line cannot slip in while the return is being posted. A
-- line is a line of the return's own goods received note: the same item, in the unit it was
-- received in, for no more than arrived. Where it names a bill line, that is a line of goods of
-- a posted bill of the same supplier for that very line of goods received, for no more than
-- it billed. The only things ever changed on a line are its figures, and only the posting
-- function can: the app's role has no right to update a line at all.
CREATE FUNCTION app.check_supplier_return_line() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid;
  v_doc public.supplier_returns%ROWTYPE;
  v_scope uuid[] := app.tenant_branch_ids();
  v_figures text[] := ARRAY['stock_value', 'grni_value', 'amount', 'sales_tax'];
  v_held boolean;
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    v_tenant := OLD.tenant_id;
  ELSE
    v_tenant := NEW.tenant_id;
  END IF;
  IF v_tenant IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  -- Held the way an update holds a row: two sessions that each add a line and then post would
  -- otherwise each wait for the other to let go.
  SELECT d.* INTO v_doc FROM public.supplier_returns d
    WHERE d.tenant_id = v_tenant AND d.id = (CASE WHEN TG_OP = 'DELETE' THEN OLD.return_id ELSE NEW.return_id END)
    FOR NO KEY UPDATE;
  v_held := FOUND;
  -- Nothing is written into, or taken out of, a return this guard has not seen and held as one
  -- the member may write. The statement above finds nothing for a return that was removed and
  -- written again under the same id by a transaction that ended while this one waited; the
  -- policy would still see the old draft and the foreign key the new row, posted or not, so the
  -- line slipped in unchecked (found by this migration's reviewer, 2026-11-17; the same fix as
  -- the joint migration 0033_line_guards made to the other guards). Refused here, in the words
  -- the policy uses, the same for a return that is not there and one the member may not write.
  IF (NOT v_held AND TG_OP = 'INSERT')
     OR (v_held AND TG_OP IN ('INSERT', 'DELETE') AND NOT coalesce(app.tenant_role() IN ('owner', 'accountant') AND (v_scope IS NULL OR v_doc.branch_id = ANY (v_scope)), false)) THEN
    IF TG_OP = 'DELETE' THEN
      RAISE EXCEPTION 'a row of table "%" is taken out only of a document the member may write', TG_TABLE_NAME USING ERRCODE = 'insufficient_privilege';
    END IF;
    RAISE EXCEPTION 'new row violates row-level security policy for table "%"', TG_TABLE_NAME USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NOT v_held OR v_doc.status <> 'draft' OR (to_jsonb(NEW) - v_figures) IS DISTINCT FROM (to_jsonb(OLD) - v_figures) THEN
      RAISE EXCEPTION 'a line of a return is replaced, not changed' USING ERRCODE = 'SE249';
    END IF;
    RETURN NEW;
  END IF;
  -- The rest is said only to a member who could have written the return: anyone else is
  -- refused by the policies, in the same words as for a return that is not there at all.
  IF v_held AND app.tenant_role() IN ('owner', 'accountant') AND (v_scope IS NULL OR v_doc.branch_id = ANY (v_scope)) THEN
    IF v_doc.status <> 'draft' THEN
      RAISE EXCEPTION 'a line is written only while its return is a draft' USING ERRCODE = 'SE249';
    END IF;
    IF TG_OP = 'INSERT' THEN
      IF NEW.stock_value IS NOT NULL OR NEW.grni_value IS NOT NULL OR NEW.amount IS NOT NULL OR NEW.sales_tax IS NOT NULL THEN
        RAISE EXCEPTION 'the figures of a line are worked out when the return is posted' USING ERRCODE = 'SE249';
      END IF;
      IF NOT EXISTS (
        SELECT 1 FROM public.goods_receipt_lines g
        WHERE g.tenant_id = v_tenant AND g.id = NEW.receipt_line_id AND g.receipt_id = v_doc.receipt_id
          AND g.item_id = NEW.item_id AND g.unit_factor = NEW.unit_factor AND g.quantity >= NEW.quantity
      ) THEN
        RAISE EXCEPTION 'a line of a return is a line of its goods received note, in the unit it was received in, for no more than arrived' USING ERRCODE = 'SE249';
      END IF;
      IF NEW.bill_line_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.supplier_bill_lines l
        JOIN public.supplier_bills b ON b.tenant_id = l.tenant_id AND b.id = l.bill_id
        WHERE l.tenant_id = v_tenant AND l.id = NEW.bill_line_id AND l.kind = 'goods' AND l.receipt_line_id = NEW.receipt_line_id
          AND l.quantity >= NEW.quantity AND b.status = 'posted' AND b.supplier_id = v_doc.supplier_id
      ) THEN
        RAISE EXCEPTION 'billed goods are sent back against the line of the posted bill that billed them, for no more than it billed' USING ERRCODE = 'SE249';
      END IF;
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  NEW.created_at := now();
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_supplier_return_line() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER supplier_return_lines_check
  BEFORE INSERT OR UPDATE OR DELETE ON public.supplier_return_lines
  FOR EACH ROW EXECUTE FUNCTION app.check_supplier_return_line();
--> statement-breakpoint
ALTER TABLE public.supplier_return_lines ENABLE ALWAYS TRIGGER supplier_return_lines_check;
--> statement-breakpoint

-- What a return's credit was set against is written once, by the functions below, and stays.
CREATE FUNCTION app.refuse_supplier_return_allocation_change() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'what a return''s credit was set against is never changed or removed' USING ERRCODE = 'SE248';
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.refuse_supplier_return_allocation_change() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER supplier_return_allocations_keep
  BEFORE UPDATE OR DELETE ON public.supplier_return_allocations
  FOR EACH ROW EXECUTE FUNCTION app.refuse_supplier_return_allocation_change();
--> statement-breakpoint
ALTER TABLE public.supplier_return_allocations ENABLE ALWAYS TRIGGER supplier_return_allocations_keep;
--> statement-breakpoint

-- ── hand-written: the lists the whole app shares ────────────────────────────────────────────────
-- Each added with a function of this step's own, as drizzle/0019_journal_documents.sql says.
-- (A return already takes a number: DB, a debit note, is among the kinds the product numbers.)

-- The journal of a return stands with the posted return that names it. It is never reversed:
-- it has no function for a reversal, so one is refused.
CREATE FUNCTION app.journal_backed_supplier_return(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.supplier_returns r
      WHERE r.tenant_id = p_journal.tenant_id AND r.id = p_journal.source_id AND r.journal_id = p_journal.id AND r.status = 'posted'
        AND r.number = p_journal.document_number AND r.return_date = p_journal.journal_date)
  $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.journal_backed_supplier_return(public.journals) FROM PUBLIC;
--> statement-breakpoint
-- The audit rows only the functions below write: the app's role cannot write a look-alike.
CREATE FUNCTION app.audit_reserved_supplier_return(p_action text) RETURNS boolean
  LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp
  AS $$ SELECT p_action IN ('supplier_return.post', 'supplier_return.apply_credit') $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.audit_reserved_supplier_return(text) FROM PUBLIC;
--> statement-breakpoint

-- ── hand-written: what earlier steps of this track must now count ───────────────────────────────
-- What is still owed on a posted bill: what it left owed to the supplier, less what posted
-- payments have settled of it (Step 26), and now less what returns' credits were set against
-- it. Null for anything that is not a posted bill of the tenant.
CREATE OR REPLACE FUNCTION app.bill_owed(p_tenant uuid, p_bill uuid) RETURNS numeric
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT b.payable - coalesce((
      SELECT sum(a.amount) FROM public.supplier_payment_allocations a
      JOIN public.supplier_payments p ON p.tenant_id = a.tenant_id AND p.id = a.payment_id
      WHERE a.tenant_id = b.tenant_id AND a.bill_id = b.id AND p.status = 'posted'), 0)
      - coalesce((
      SELECT sum(r.amount) FROM public.supplier_return_allocations r
      WHERE r.tenant_id = b.tenant_id AND r.bill_id = b.id), 0)
    FROM public.supplier_bills b WHERE b.tenant_id = p_tenant AND b.id = p_bill AND b.status = 'posted'
  $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.bill_owed(uuid, uuid) FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.bill_owed(uuid, uuid) FROM app_runtime, anon, authenticated, service_role;
--> statement-breakpoint

-- Posting a bill (Step 25), written out again with two things changed, both marked "Step 27":
-- goods sent back before they were billed can no longer be billed, and what a bill clears from
-- Goods received not invoiced leaves out what those returns already took off it. The rest is
-- drizzle/0030_supplier_bills.sql word for word.
CREATE OR REPLACE FUNCTION app.post_supplier_bill(p_bill uuid) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_doc public.supplier_bills%ROWTYPE;
  v_supplier public.suppliers%ROWTYPE;
  v_registered boolean;
  v_withholds boolean;
  v_on_list boolean;
  v_line record;
  v_rule public.withholding_rules%ROWTYPE;
  v_rate numeric;
  v_billed numeric;
  v_cleared numeric;
  v_returned numeric;
  v_reversed numeric;
  v_value numeric;
  v_lines integer := 0;
  v_amount numeric := 0;
  v_tax numeric := 0;
  v_grni numeric := 0;
  v_difference numeric := 0;
  v_services numeric := 0;
  v_expense_lines integer := 0;
  v_provincial numeric := 0;
  v_provincial_rule public.withholding_rules%ROWTYPE;
  v_total numeric;
  v_base numeric;
  v_withheld numeric := 0;
  v_entries jsonb := '[]'::jsonb;
  v_entry jsonb;
  v_share numeric;
  v_shared numeric := 0;
  v_seen integer := 0;
  v_number text;
  v_journal uuid;
  v_no integer := 0;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant') THEN
    RAISE EXCEPTION 'this role cannot post supplier bills' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'purchase documents are written in read committed transactions' USING ERRCODE = 'SE219';
  END IF;
  SELECT d.* INTO v_doc FROM public.supplier_bills d WHERE d.tenant_id = v_tenant AND d.id = p_bill FOR UPDATE;
  IF NOT FOUND OR (v_scope IS NOT NULL AND NOT (v_doc.branch_id = ANY (v_scope))) THEN
    RAISE EXCEPTION 'no such supplier bill in this company' USING ERRCODE = 'SE223';
  END IF;
  IF v_doc.status <> 'draft' THEN
    RAISE EXCEPTION 'only a draft bill is posted' USING ERRCODE = 'SE224';
  END IF;
  -- Nothing is recorded before it happens. The day is Pakistan's, as everywhere in the product
  -- until a company can choose its own time zone; not the session's, which a caller can set.
  IF v_doc.bill_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'that date has not come yet' USING ERRCODE = 'SE233';
  END IF;
  PERFORM app.require_open_period(v_tenant, v_doc.bill_date);
  -- The supplier is held until the transaction ends: its bills are posted one at a time, so
  -- two cannot carry the same invoice number or bill the same goods twice.
  SELECT s.* INTO v_supplier FROM public.suppliers s WHERE s.tenant_id = v_tenant AND s.id = v_doc.supplier_id FOR NO KEY UPDATE;
  IF EXISTS (
    SELECT 1 FROM public.supplier_bills b
    WHERE b.tenant_id = v_tenant AND b.supplier_id = v_doc.supplier_id AND b.status = 'posted'
      AND lower(btrim(b.supplier_invoice_no)) = lower(btrim(v_doc.supplier_invoice_no))
  ) THEN
    RAISE EXCEPTION 'the supplier''s invoice % is already on a posted bill', v_doc.supplier_invoice_no USING ERRCODE = 'SE232';
  END IF;
  v_registered := coalesce((SELECT c.sales_tax_registered FROM public.company_setup c WHERE c.tenant_id = v_tenant), false);
  v_withholds := coalesce((SELECT p.withholding_on FROM public.purchase_settings p WHERE p.tenant_id = v_tenant), false);
  v_on_list := v_supplier.atl_status = 'active';
  IF NOT v_withholds AND (v_doc.income_tax_code IS NOT NULL OR v_doc.sales_tax_code IS NOT NULL OR v_doc.provincial_tax_code IS NOT NULL) THEN
    RAISE EXCEPTION 'this company does not withhold tax from its suppliers' USING ERRCODE = 'SE231';
  END IF;

  -- The lines, in their order. Goods clear what they came in at; every line's tax is the table's.
  FOR v_line IN
    SELECT l.*, g.quantity AS received, g.id AS found_line, r.status AS receipt_status, r.supplier_id AS receipt_supplier, w.branch_id AS receipt_branch,
           i.code AS item_code, c.kind::text AS category_kind,
           (SELECT m.value FROM public.stock_moves m
              WHERE m.tenant_id = l.tenant_id AND m.source_type = 'goods_receipt' AND m.source_id = r.id AND m.source_line_id = g.id) AS received_at
    FROM public.supplier_bill_lines l
    LEFT JOIN public.goods_receipt_lines g ON g.tenant_id = l.tenant_id AND g.id = l.receipt_line_id
    LEFT JOIN public.goods_receipts r ON r.tenant_id = g.tenant_id AND r.id = g.receipt_id
    LEFT JOIN public.warehouses w ON w.tenant_id = r.tenant_id AND w.id = r.warehouse_id
    LEFT JOIN public.items i ON i.tenant_id = l.tenant_id AND i.id = l.item_id
    LEFT JOIN public.tax_categories c ON c.tenant_id = l.tenant_id AND c.id = l.tax_category_id
    WHERE l.tenant_id = v_tenant AND l.bill_id = v_doc.id
    ORDER BY l.line_no
  LOOP
    v_lines := v_lines + 1;
    v_amount := v_amount + v_line.amount;
    IF v_line.kind = 'goods' THEN
      IF v_line.found_line IS NULL OR v_line.receipt_status <> 'posted' OR v_line.receipt_supplier <> v_doc.supplier_id
         OR v_line.receipt_branch <> v_doc.branch_id OR v_line.received_at IS NULL THEN
        RAISE EXCEPTION 'a line of goods is a line of a posted goods received note, from the bill''s supplier, into the bill''s branch' USING ERRCODE = 'SE226';
      END IF;
      SELECT coalesce(sum(o.quantity), 0), coalesce(sum(o.received_value), 0) INTO v_billed, v_cleared
        FROM public.supplier_bill_lines o
        JOIN public.supplier_bills b ON b.tenant_id = o.tenant_id AND b.id = o.bill_id
        WHERE o.tenant_id = v_tenant AND o.receipt_line_id = v_line.receipt_line_id AND b.status = 'posted';
      -- Step 27: what was sent back to the supplier before it was billed is not billed, and has
      -- already come off Goods received not invoiced.
      SELECT coalesce(sum(x.quantity), 0), coalesce(sum(x.grni_value), 0) INTO v_returned, v_reversed
        FROM public.supplier_return_lines x
        JOIN public.supplier_returns d ON d.tenant_id = x.tenant_id AND d.id = x.return_id
        WHERE x.tenant_id = v_tenant AND x.receipt_line_id = v_line.receipt_line_id AND x.bill_line_id IS NULL AND d.status = 'posted';
      IF v_billed + v_returned + v_line.quantity > v_line.received THEN
        RAISE EXCEPTION 'more of % billed than was received and is not yet billed: % received, % already billed, % sent back, % on this bill',
          v_line.item_code, v_line.received, v_billed, v_returned, v_line.quantity USING ERRCODE = 'SE228';
      END IF;
      -- What all that is billed or sent back of the line so far should have cleared, less what earlier bills and returns did.
      v_value := round(v_line.received_at * (v_billed + v_returned + v_line.quantity) / v_line.received, 2) - v_cleared - v_reversed;
      UPDATE public.supplier_bill_lines o SET received_value = v_value WHERE o.tenant_id = v_tenant AND o.id = v_line.id;
      v_grni := v_grni + v_value;
      v_difference := v_difference + v_line.amount - v_value;
    ELSE
      v_services := v_services + v_line.amount;
      v_expense_lines := v_expense_lines + 1;
    END IF;
    IF v_line.tax_category_id IS NULL THEN
      IF v_line.sales_tax <> 0 OR v_line.tax_rate IS NOT NULL THEN
        RAISE EXCEPTION 'line % carries sales tax and names no tax category', v_line.line_no USING ERRCODE = 'SE227';
      END IF;
    ELSE
      IF NOT v_registered OR v_supplier.registration_type <> 'registered' OR v_supplier.strn IS NULL THEN
        RAISE EXCEPTION 'sales tax on a bill needs the company registered for sales tax and a supplier registered with an STRN' USING ERRCODE = 'SE229';
      END IF;
      -- Goods taxed on their retail price (the Third Schedule) are not billed here yet: the
      -- tax on them is not the bill's value at the rate.
      IF v_line.category_kind IS NULL OR v_line.category_kind = 'third_schedule' THEN
        RAISE EXCEPTION 'line %: goods taxed on their retail price cannot carry input tax on a bill yet', v_line.line_no USING ERRCODE = 'SE230';
      END IF;
      SELECT t.rate INTO v_rate FROM public.tax_rates t
        WHERE t.tenant_id = v_tenant AND t.category_id = v_line.tax_category_id AND t.effective_from <= v_doc.bill_date
        ORDER BY t.effective_from DESC LIMIT 1;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'line %: no sales tax rate is in force for its category on %', v_line.line_no, v_doc.bill_date USING ERRCODE = 'SE230';
      END IF;
      IF v_line.tax_rate IS DISTINCT FROM v_rate OR v_line.sales_tax <> round(v_line.amount * v_rate / 100, 2) THEN
        RAISE EXCEPTION 'line %: the sales tax is not what the rate in force gives', v_line.line_no USING ERRCODE = 'SE227';
      END IF;
      v_tax := v_tax + v_line.sales_tax;
    END IF;
  END LOOP;
  IF v_lines = 0 THEN
    RAISE EXCEPTION 'a bill is posted with at least one line' USING ERRCODE = 'SE227';
  END IF;

  -- The province's tax on services: charged by the supplier on the services billed, at the
  -- province's rate, and withheld whole.
  IF v_doc.provincial_tax_code IS NOT NULL THEN
    IF v_services <= 0 THEN
      RAISE EXCEPTION 'the province''s tax is on services, and the bill has no service or expense line' USING ERRCODE = 'SE227';
    END IF;
    v_provincial_rule := app.withholding_rule_on(v_tenant, 'provincial_sales_tax', v_doc.provincial_tax_code, v_doc.bill_date);
    v_provincial := round(v_services * v_provincial_rule.rate / 100, 2);
  END IF;
  v_total := v_amount + v_tax + v_provincial;
  IF v_doc.amount <> v_amount OR v_doc.sales_tax <> v_tax OR v_doc.provincial_tax <> v_provincial OR v_total <= 0 THEN
    RAISE EXCEPTION 'the bill''s figures are not its lines'' and the tables'': amount %, sales tax %, provincial tax %', v_amount, v_tax, v_provincial USING ERRCODE = 'SE227';
  END IF;

  -- What is withheld, each from its line of the tables, at the rate for whether the supplier
  -- is on the Active Taxpayers List as recorded today.
  IF v_doc.income_tax_code IS NOT NULL THEN
    v_rule := app.withholding_rule_on(v_tenant, 'income_tax', v_doc.income_tax_code, v_doc.bill_date);
    v_rate := CASE WHEN v_on_list THEN v_rule.rate ELSE coalesce(v_rule.rate_non_atl, v_rule.rate) END;
    v_base := CASE v_rule.base::text WHEN 'gross_amount' THEN v_total WHEN 'taxable_value' THEN v_amount ELSE v_tax END;
    IF v_base <= 0 OR v_rate <= 0 THEN
      RAISE EXCEPTION 'there is nothing on the bill for the income tax line to be withheld from' USING ERRCODE = 'SE227';
    END IF;
    v_entries := v_entries || jsonb_build_object('kind', 'income_tax', 'control', 'wht_income_tax', 'rule', v_rule.id, 'code', v_rule.code,
      'law', v_rule.legal_reference, 'base', v_base, 'rate', v_rate, 'amount', round(v_base * v_rate / 100, 2));
  END IF;
  IF v_doc.sales_tax_code IS NOT NULL THEN
    v_rule := app.withholding_rule_on(v_tenant, 'sales_tax', v_doc.sales_tax_code, v_doc.bill_date);
    v_rate := CASE WHEN v_on_list THEN v_rule.rate ELSE coalesce(v_rule.rate_non_atl, v_rule.rate) END;
    v_base := CASE v_rule.base::text WHEN 'gross_amount' THEN v_total WHEN 'taxable_value' THEN v_amount ELSE v_tax END;
    IF NOT v_registered OR v_base <= 0 OR v_rate <= 0 THEN
      RAISE EXCEPTION 'there is nothing on the bill for the sales tax line to be withheld from' USING ERRCODE = 'SE227';
    END IF;
    v_entries := v_entries || jsonb_build_object('kind', 'sales_tax', 'control', 'wht_sales_tax', 'rule', v_rule.id, 'code', v_rule.code,
      'law', v_rule.legal_reference, 'base', v_base, 'rate', v_rate, 'amount', round(v_base * v_rate / 100, 2));
  END IF;
  IF v_doc.provincial_tax_code IS NOT NULL THEN
    v_entries := v_entries || jsonb_build_object('kind', 'provincial_sales_tax', 'control', 'wht_provincial_tax', 'rule', v_provincial_rule.id,
      'code', v_provincial_rule.code, 'law', v_provincial_rule.legal_reference, 'base', v_services, 'rate', v_provincial_rule.rate, 'amount', v_provincial);
  END IF;
  SELECT coalesce(sum((e.value->>'amount')::numeric), 0) INTO v_withheld FROM jsonb_array_elements(v_entries) AS e(value);
  IF v_withheld > v_total OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_entries) AS e(value) WHERE (e.value->>'amount')::numeric <= 0) THEN
    RAISE EXCEPTION 'what would be withheld is not an amount between nothing and the bill' USING ERRCODE = 'SE227';
  END IF;

  v_number := app.next_document_number('PB', v_doc.bill_date);
  -- The balance, and the document behind the journal, are asked when the transaction ends, whatever the caller set before this.
  SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
  INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
    VALUES (v_tenant, v_doc.bill_date, 'supplier_bill', v_doc.id, v_number, left('Bill ' || btrim(v_doc.supplier_invoice_no) || ' from ' || v_supplier.name, 500), v_doc.branch_id, v_user)
    RETURNING id INTO v_journal;
  IF v_grni > 0 THEN
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'grni'), v_grni, 0, 'Goods received, now billed');
  END IF;
  IF v_difference <> 0 THEN
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'purchase_price_difference'), greatest(v_difference, 0), greatest(-v_difference, 0),
              'Billed at a different price from the order');
  END IF;
  -- Each expense line, with its share of the province's tax: in proportion, the last line taking what is left.
  FOR v_line IN
    SELECT l.account_id, l.description, l.amount FROM public.supplier_bill_lines l
    WHERE l.tenant_id = v_tenant AND l.bill_id = v_doc.id AND l.kind = 'expense' ORDER BY l.line_no
  LOOP
    v_seen := v_seen + 1;
    v_share := CASE WHEN v_seen = v_expense_lines THEN v_provincial - v_shared ELSE round(v_provincial * v_line.amount / v_services, 2) END;
    v_shared := v_shared + v_share;
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_no, v_line.account_id, v_line.amount + v_share, 0, v_line.description);
  END LOOP;
  IF v_tax > 0 THEN
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'input_tax'), v_tax, 0, 'Input tax on ' || v_number);
  END IF;
  FOR v_entry IN SELECT e.value FROM jsonb_array_elements(v_entries) AS e(value)
  LOOP
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
      VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, v_entry->>'control'), 0, (v_entry->>'amount')::numeric,
              'Withheld from ' || v_supplier.name || ' at ' || trim_scale((v_entry->>'rate')::numeric)::text || '%');
    INSERT INTO public.withholding_entries (tenant_id, bill_id, supplier_id, entry_date, kind, rule_id, code, legal_reference, on_active_list, base_amount, rate, amount, journal_id, created_by)
      VALUES (v_tenant, v_doc.id, v_doc.supplier_id, v_doc.bill_date, v_entry->>'kind', (v_entry->>'rule')::uuid, v_entry->>'code', v_entry->>'law', v_on_list,
              (v_entry->>'base')::numeric, (v_entry->>'rate')::numeric, (v_entry->>'amount')::numeric, v_journal, v_user);
  END LOOP;
  IF v_total - v_withheld > 0 THEN
    v_no := v_no + 1;
    INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description, supplier_id)
      VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'ap'), 0, v_total - v_withheld, 'Bill ' || btrim(v_doc.supplier_invoice_no), v_doc.supplier_id);
  END IF;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'journal.post', 'journal', v_journal,
      jsonb_build_object('date', v_doc.bill_date, 'source', 'supplier_bill', 'sourceId', v_doc.id, 'number', v_number, 'lines', v_no, 'total', v_total::text));

  UPDATE public.supplier_bills d SET status = 'posted', number = v_number, withheld = v_withheld, payable = v_total - v_withheld,
      journal_id = v_journal, posted_at = now(), posted_by = v_user, updated_by = v_user
    WHERE d.tenant_id = v_tenant AND d.id = v_doc.id;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'supplier_bill.post', 'supplier_bill', v_doc.id,
      jsonb_build_object('number', v_number, 'supplier', v_supplier.name, 'invoice', btrim(v_doc.supplier_invoice_no), 'date', v_doc.bill_date,
        'total', v_total::text, 'withheld', v_withheld::text, 'payable', (v_total - v_withheld)::text, 'journalId', v_journal));
  RETURN v_number;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.post_supplier_bill(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.post_supplier_bill(uuid) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: posting a return ──────────────────────────────────────────────────────────────
-- Not for the app to call: a return's row, held for the rest of the transaction, for a member
-- who may write returns; to anyone else, and outside a member's branches, it does not exist.
-- The supplier is held too, as posting a bill and paying do: bills, payments and returns of one
-- supplier take their turn, so the same goods cannot be billed and sent back unbilled at once,
-- and a bill cannot be settled past what is owed on it.
CREATE FUNCTION app.hold_supplier_return(p_return uuid) RETURNS public.supplier_returns
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_tenant uuid := app.tenant_id();
  v_role public.member_role := app.tenant_role();
  v_scope uuid[] := app.tenant_branch_ids();
  v_doc public.supplier_returns%ROWTYPE;
BEGIN
  IF v_tenant IS NULL OR app.current_user_id() IS NULL OR v_role IS NULL OR v_role NOT IN ('owner', 'accountant') THEN
    RAISE EXCEPTION 'this role cannot send goods back to suppliers' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF current_setting('transaction_isolation') <> 'read committed' THEN
    RAISE EXCEPTION 'purchase documents are written in read committed transactions' USING ERRCODE = 'SE219';
  END IF;
  SELECT d.* INTO v_doc FROM public.supplier_returns d WHERE d.tenant_id = v_tenant AND d.id = p_return FOR UPDATE;
  IF NOT FOUND OR (v_scope IS NOT NULL AND NOT (v_doc.branch_id = ANY (v_scope))) THEN
    RAISE EXCEPTION 'no such supplier return in this company' USING ERRCODE = 'SE246';
  END IF;
  PERFORM 1 FROM public.suppliers s WHERE s.tenant_id = v_tenant AND s.id = v_doc.supplier_id FOR NO KEY UPDATE;
  RETURN v_doc;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.hold_supplier_return(uuid) FROM PUBLIC;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.hold_supplier_return(uuid) FROM app_runtime, anon, authenticated, service_role;
--> statement-breakpoint

-- One act of the database, whole or not at all. The return takes its DB number. Each line's
-- goods leave the note's warehouse at what the stock is carried at; a line of goods not billed
-- takes off Goods received not invoiced what that much of the goods came into stock at (to the
-- paisa: what all that has been billed or sent back of the line so far should have cleared,
-- less what was cleared before); a line of billed goods takes off what is owed to the supplier
-- what that much of the bill line charged, with its sales tax (worked the same way, so a bill
-- line sent back whole gives back exactly what it charged). The journal is posted, and what the
-- supplier owes back is set against each bill the goods were billed on, as far as it is owed.
--
-- Refused: a return that is not a draft (SE247), no lines (SE250), a line that is not of the
-- note or of a posted bill of its goods (SE249), more than was received and is left (SE251), a
-- date that has not come or is before the goods were received or billed (SE252), not enough in
-- the warehouse (SE060), a closed period.
CREATE FUNCTION app.post_supplier_return(p_return uuid) RETURNS text
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_doc public.supplier_returns%ROWTYPE := app.hold_supplier_return(p_return);
  v_tenant uuid := v_doc.tenant_id;
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_receipt public.goods_receipts%ROWTYPE;
  v_supplier text;
  v_warehouse text;
  v_line record;
  v_bill record;
  v_billed numeric;
  v_cleared numeric;
  v_returned numeric;
  v_reversed numeric;
  v_back numeric;
  v_tax_back numeric;
  v_value numeric;
  v_part numeric;
  v_part_tax numeric;
  v_out numeric;
  v_lines integer := 0;
  v_stock numeric := 0;
  v_grni numeric := 0;
  v_amount numeric := 0;
  v_tax numeric := 0;
  v_difference numeric;
  v_credits jsonb := '{}'::jsonb;
  v_applied numeric := 0;
  v_owed numeric;
  v_number text;
  v_journal uuid;
  v_no integer := 0;
BEGIN
  IF v_doc.status <> 'draft' THEN
    RAISE EXCEPTION 'only a draft return is posted' USING ERRCODE = 'SE247';
  END IF;
  -- Nothing is recorded before it happens. The day is Pakistan's, as everywhere in the product
  -- until a company can choose its own time zone; not the session's, which a caller can set.
  IF v_doc.return_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'that date has not come yet' USING ERRCODE = 'SE252';
  END IF;
  SELECT r.* INTO v_receipt FROM public.goods_receipts r WHERE r.tenant_id = v_tenant AND r.id = v_doc.receipt_id;
  IF NOT FOUND OR v_receipt.status <> 'posted' OR v_receipt.supplier_id <> v_doc.supplier_id OR v_receipt.warehouse_id <> v_doc.warehouse_id
     OR NOT EXISTS (SELECT 1 FROM public.warehouses w WHERE w.tenant_id = v_tenant AND w.id = v_doc.warehouse_id AND w.branch_id = v_doc.branch_id) THEN
    RAISE EXCEPTION 'goods are sent back against a posted goods received note, to its supplier, out of its warehouse' USING ERRCODE = 'SE254';
  END IF;
  IF v_doc.return_date < v_receipt.receipt_date THEN
    RAISE EXCEPTION 'goods are sent back on or after the day they were received' USING ERRCODE = 'SE252';
  END IF;
  PERFORM app.require_open_period(v_tenant, v_doc.return_date);
  SELECT s.name INTO v_supplier FROM public.suppliers s WHERE s.tenant_id = v_tenant AND s.id = v_doc.supplier_id;
  SELECT w.name INTO v_warehouse FROM public.warehouses w WHERE w.tenant_id = v_tenant AND w.id = v_doc.warehouse_id;

  -- Every balance this return touches is held first, item by item, as for every stock document.
  PERFORM 1 FROM public.stock_balances b
    WHERE b.tenant_id = v_tenant AND b.warehouse_id = v_doc.warehouse_id
      AND b.item_id IN (SELECT l.item_id FROM public.supplier_return_lines l WHERE l.tenant_id = v_tenant AND l.return_id = v_doc.id)
    ORDER BY b.item_id
    FOR UPDATE;

  v_number := app.next_document_number('DB', v_doc.return_date);
  FOR v_line IN
    SELECT l.id, l.line_no, l.receipt_line_id, l.bill_line_id, l.item_id, l.unit_factor, l.quantity, l.base_quantity, i.code AS item_code,
           g.receipt_id AS line_receipt, g.item_id AS received_item, g.unit_factor AS received_factor, g.quantity AS received,
           (SELECT m.value FROM public.stock_moves m
              WHERE m.tenant_id = l.tenant_id AND m.source_type = 'goods_receipt' AND m.source_id = g.receipt_id AND m.source_line_id = g.id) AS received_at,
           bl.kind AS bill_kind, bl.receipt_line_id AS bill_receipt_line, bl.quantity AS bill_quantity, bl.amount AS bill_amount, bl.sales_tax AS bill_tax,
           b.id AS bill_id, b.status AS bill_status, b.supplier_id AS bill_supplier, b.branch_id AS bill_branch, b.bill_date, b.number AS bill_number
    FROM public.supplier_return_lines l
    JOIN public.items i ON i.tenant_id = l.tenant_id AND i.id = l.item_id
    LEFT JOIN public.goods_receipt_lines g ON g.tenant_id = l.tenant_id AND g.id = l.receipt_line_id
    LEFT JOIN public.supplier_bill_lines bl ON bl.tenant_id = l.tenant_id AND bl.id = l.bill_line_id
    LEFT JOIN public.supplier_bills b ON b.tenant_id = bl.tenant_id AND b.id = bl.bill_id
    WHERE l.tenant_id = v_tenant AND l.return_id = v_doc.id
    ORDER BY l.item_id, l.line_no
  LOOP
    v_lines := v_lines + 1;
    IF v_line.line_receipt IS DISTINCT FROM v_doc.receipt_id OR v_line.received_item <> v_line.item_id OR v_line.received_factor <> v_line.unit_factor
       OR v_line.received_at IS NULL THEN
      RAISE EXCEPTION 'a line of a return is a line of its goods received note, in the unit it was received in' USING ERRCODE = 'SE249';
    END IF;
    IF v_line.bill_line_id IS NULL THEN
      -- Goods no bill has billed. What bills and earlier returns have taken of the line so far:
      SELECT coalesce(sum(o.quantity), 0), coalesce(sum(o.received_value), 0) INTO v_billed, v_cleared
        FROM public.supplier_bill_lines o
        JOIN public.supplier_bills ob ON ob.tenant_id = o.tenant_id AND ob.id = o.bill_id
        WHERE o.tenant_id = v_tenant AND o.receipt_line_id = v_line.receipt_line_id AND ob.status = 'posted';
      SELECT coalesce(sum(x.quantity), 0), coalesce(sum(x.grni_value), 0) INTO v_returned, v_reversed
        FROM public.supplier_return_lines x
        JOIN public.supplier_returns d ON d.tenant_id = x.tenant_id AND d.id = x.return_id
        WHERE x.tenant_id = v_tenant AND x.receipt_line_id = v_line.receipt_line_id AND x.bill_line_id IS NULL AND d.status = 'posted';
      IF v_billed + v_returned + v_line.quantity > v_line.received THEN
        RAISE EXCEPTION 'more of % sent back than was received and is not yet billed: % received, % billed, % already sent back, % on this return',
          v_line.item_code, v_line.received, v_billed, v_returned, v_line.quantity USING ERRCODE = 'SE251';
      END IF;
      v_value := round(v_line.received_at * (v_billed + v_returned + v_line.quantity) / v_line.received, 2) - v_cleared - v_reversed;
      v_out := app.move_stock(v_tenant, v_user, v_line.item_id, v_doc.warehouse_id, v_doc.return_date, -v_line.base_quantity, NULL, 'supplier_return', v_doc.id, v_line.id);
      UPDATE public.supplier_return_lines x SET stock_value = v_out, grni_value = v_value WHERE x.tenant_id = v_tenant AND x.id = v_line.id;
      v_grni := v_grni + v_value;
    ELSE
      -- Goods a posted bill billed: its own line, for these very goods, of this supplier and branch.
      IF v_line.bill_kind IS DISTINCT FROM 'goods' OR v_line.bill_receipt_line IS DISTINCT FROM v_line.receipt_line_id OR v_line.bill_status IS DISTINCT FROM 'posted'
         OR v_line.bill_supplier <> v_doc.supplier_id OR v_line.bill_branch <> v_doc.branch_id THEN
        RAISE EXCEPTION 'billed goods are sent back against the line of the posted bill that billed them' USING ERRCODE = 'SE249';
      END IF;
      IF v_doc.return_date < v_line.bill_date THEN
        RAISE EXCEPTION 'billed goods are sent back on or after the day of their bill' USING ERRCODE = 'SE252';
      END IF;
      SELECT coalesce(sum(x.quantity), 0), coalesce(sum(x.amount), 0), coalesce(sum(x.sales_tax), 0) INTO v_returned, v_back, v_tax_back
        FROM public.supplier_return_lines x
        JOIN public.supplier_returns d ON d.tenant_id = x.tenant_id AND d.id = x.return_id
        WHERE x.tenant_id = v_tenant AND x.bill_line_id = v_line.bill_line_id AND d.status = 'posted';
      IF v_returned + v_line.quantity > v_line.bill_quantity THEN
        RAISE EXCEPTION 'more of % sent back than bill % billed: % billed, % already sent back, % on this return',
          v_line.item_code, v_line.bill_number, v_line.bill_quantity, v_returned, v_line.quantity USING ERRCODE = 'SE251';
      END IF;
      v_part := round(v_line.bill_amount * (v_returned + v_line.quantity) / v_line.bill_quantity, 2) - v_back;
      v_part_tax := round(v_line.bill_tax * (v_returned + v_line.quantity) / v_line.bill_quantity, 2) - v_tax_back;
      v_out := app.move_stock(v_tenant, v_user, v_line.item_id, v_doc.warehouse_id, v_doc.return_date, -v_line.base_quantity, NULL, 'supplier_return', v_doc.id, v_line.id);
      UPDATE public.supplier_return_lines x SET stock_value = v_out, amount = v_part, sales_tax = v_part_tax WHERE x.tenant_id = v_tenant AND x.id = v_line.id;
      v_amount := v_amount + v_part;
      v_tax := v_tax + v_part_tax;
      v_credits := jsonb_set(v_credits, ARRAY[v_line.bill_id::text], to_jsonb(coalesce((v_credits->>(v_line.bill_id::text))::numeric, 0) + v_part + v_part_tax));
    END IF;
    v_stock := v_stock + v_out;
  END LOOP;
  IF v_lines = 0 THEN
    RAISE EXCEPTION 'a return is posted with at least one line' USING ERRCODE = 'SE250';
  END IF;

  -- What came off the books' side (goods received not invoiced, and the supplier) less what
  -- left stock: above nothing where the goods were carried at less than is taken back for them.
  v_difference := v_grni + v_amount - v_stock;
  IF v_grni > 0 OR v_amount + v_tax > 0 OR v_stock > 0 THEN
    -- The balance, and the document behind the journal, are asked when the transaction ends, whatever the caller set before this.
    SET CONSTRAINTS public.journals_balanced, public.journal_lines_balanced, public.journals_with_document DEFERRED;
    INSERT INTO public.journals (tenant_id, journal_date, source_type, source_id, document_number, memo, branch_id, created_by)
      VALUES (v_tenant, v_doc.return_date, 'supplier_return', v_doc.id, v_number, left('Goods sent back to ' || v_supplier || ' from ' || v_receipt.number, 500), v_doc.branch_id, v_user)
      RETURNING id INTO v_journal;
    IF v_grni > 0 THEN
      v_no := v_no + 1;
      INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
        VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'grni'), v_grni, 0, 'Goods sent back before they were billed');
    END IF;
    IF v_amount + v_tax > 0 THEN
      v_no := v_no + 1;
      INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description, supplier_id)
        VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'ap'), v_amount + v_tax, 0, 'Debit note ' || v_number, v_doc.supplier_id);
    END IF;
    IF v_difference <> 0 THEN
      v_no := v_no + 1;
      INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
        VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'purchase_price_difference'), greatest(-v_difference, 0), greatest(v_difference, 0),
                'Sent back at a different value from what the stock was carried at');
    END IF;
    IF v_tax > 0 THEN
      v_no := v_no + 1;
      INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
        VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'input_tax'), 0, v_tax, 'Input tax on goods sent back, ' || v_number);
    END IF;
    IF v_stock > 0 THEN
      v_no := v_no + 1;
      INSERT INTO public.journal_lines (tenant_id, journal_id, line_no, account_id, debit, credit, description)
        VALUES (v_tenant, v_journal, v_no, app.control_account(v_tenant, 'inventory'), 0, v_stock, 'Goods sent back to the supplier');
    END IF;
    INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
      VALUES (v_tenant, v_user, v_role, 'journal.post', 'journal', v_journal,
        jsonb_build_object('date', v_doc.return_date, 'source', 'supplier_return', 'sourceId', v_doc.id, 'number', v_number, 'lines', v_no,
          'total', (v_grni + v_amount + v_tax + greatest(-v_difference, 0))::text));
  END IF;

  UPDATE public.supplier_returns d SET status = 'posted', number = v_number, stock_value = v_stock, grni_value = v_grni, billed_amount = v_amount, sales_tax = v_tax,
      credit = v_amount + v_tax, journal_id = v_journal, posted_at = now(), posted_by = v_user, updated_by = v_user
    WHERE d.tenant_id = v_tenant AND d.id = v_doc.id;

  -- What the supplier owes back comes off each bill the goods were billed on, as far as that
  -- bill is still owed. Whatever is left is a credit with the supplier.
  FOR v_bill IN
    SELECT (c.key)::uuid AS bill_id, (c.value #>> '{}')::numeric AS credit FROM jsonb_each(v_credits) AS c(key, value) ORDER BY c.key
  LOOP
    v_owed := least(v_bill.credit, greatest(app.bill_owed(v_tenant, v_bill.bill_id), 0));
    IF v_owed > 0 THEN
      INSERT INTO public.supplier_return_allocations (tenant_id, return_id, bill_id, amount, applied_on, created_by)
        VALUES (v_tenant, v_doc.id, v_bill.bill_id, v_owed, v_doc.return_date, v_user);
      v_applied := v_applied + v_owed;
    END IF;
  END LOOP;

  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'supplier_return.post', 'supplier_return', v_doc.id,
      jsonb_build_object('number', v_number, 'supplier', v_supplier, 'receipt', v_receipt.number, 'date', v_doc.return_date, 'warehouse', v_warehouse, 'lines', v_lines,
        'stockValue', v_stock::text, 'notBilled', v_grni::text, 'credit', (v_amount + v_tax)::text, 'setAgainstBills', v_applied::text, 'journalId', v_journal));
  RETURN v_number;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.post_supplier_return(uuid) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app.post_supplier_return(uuid) TO app_runtime;
--> statement-breakpoint

-- ── hand-written: setting a return's credit against other bills ─────────────────────────────────
-- What is left of a posted return's credit (what the supplier owes back, and no bill has taken
-- yet) is set against posted bills of the same supplier and branch, on a day on or after the
-- return and each bill. p_allocations is a list of {"bill_id", "amount"}. Nothing is posted to
-- the books: the debit note already took the whole credit off what is owed to the supplier.
-- Returns how many bills it was set against.
CREATE FUNCTION app.apply_supplier_return_credit(p_return uuid, p_date date, p_allocations jsonb) RETURNS integer
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
DECLARE
  v_doc public.supplier_returns%ROWTYPE := app.hold_supplier_return(p_return);
  v_tenant uuid := v_doc.tenant_id;
  v_user uuid := app.current_user_id();
  v_role public.member_role := app.tenant_role();
  v_supplier text;
  v_left numeric;
  v_line record;
  v_total numeric := 0;
  v_lines integer := 0;
BEGIN
  IF v_doc.status <> 'posted' THEN
    RAISE EXCEPTION 'a credit is set against a bill from a posted return' USING ERRCODE = 'SE247';
  END IF;
  IF p_date IS NULL OR NOT isfinite(p_date) OR p_date < v_doc.return_date OR p_date > (now() AT TIME ZONE 'Asia/Karachi')::date THEN
    RAISE EXCEPTION 'a credit is set against a bill on a day that has come, on or after the return' USING ERRCODE = 'SE252';
  END IF;
  IF p_allocations IS NULL OR jsonb_typeof(p_allocations) <> 'array' OR jsonb_array_length(p_allocations) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'name between 1 and 200 bills to set the credit against' USING ERRCODE = 'SE253';
  END IF;
  -- Nothing is posted, but what is owed on a bill as at that day changes: not in a closed period.
  PERFORM app.require_open_period(v_tenant, p_date);
  SELECT s.name INTO v_supplier FROM public.suppliers s WHERE s.tenant_id = v_tenant AND s.id = v_doc.supplier_id;
  v_left := v_doc.credit - coalesce((SELECT sum(a.amount) FROM public.supplier_return_allocations a WHERE a.tenant_id = v_tenant AND a.return_id = v_doc.id), 0);

  FOR v_line IN
    SELECT (x.value->>'bill_id')::uuid AS bill_id, (x.value->>'amount')::numeric AS amount, b.status AS bill_status, b.supplier_id, b.branch_id, b.bill_date, b.number,
           -- By the id itself: the same id typed another way (in capitals, in braces) is the same bill.
           count(*) OVER (PARTITION BY (x.value->>'bill_id')::uuid) AS times
    FROM jsonb_array_elements(p_allocations) AS x(value)
    LEFT JOIN public.supplier_bills b ON b.tenant_id = v_tenant AND b.id = (x.value->>'bill_id')::uuid
    ORDER BY b.bill_date, b.number
  LOOP
    IF v_line.bill_status IS DISTINCT FROM 'posted' OR v_line.supplier_id <> v_doc.supplier_id OR v_line.branch_id <> v_doc.branch_id OR v_line.bill_date > p_date
       OR v_line.times > 1 THEN
      RAISE EXCEPTION 'a credit is set against posted bills of its own supplier and branch, dated on or before the day, each once' USING ERRCODE = 'SE253';
    END IF;
    -- "Not a number" passes "> 0"; the upper bound refuses it. An amount is to the paisa.
    IF v_line.amount IS NULL OR NOT (v_line.amount > 0 AND v_line.amount < 1e16) OR v_line.amount <> round(v_line.amount, 2) THEN
      RAISE EXCEPTION 'an amount set against a bill is more than nothing, to the paisa' USING ERRCODE = 'SE253';
    END IF;
    IF v_line.amount > app.bill_owed(v_tenant, v_line.bill_id) THEN
      RAISE EXCEPTION 'more set against bill % than is still owed on it', v_line.number USING ERRCODE = 'SE253';
    END IF;
    v_total := v_total + v_line.amount;
    IF v_total > v_left THEN
      RAISE EXCEPTION 'more set against bills than is left of the credit: % against %', v_total, v_left USING ERRCODE = 'SE253';
    END IF;
    INSERT INTO public.supplier_return_allocations (tenant_id, return_id, bill_id, amount, applied_on, created_by)
      VALUES (v_tenant, v_doc.id, v_line.bill_id, v_line.amount, p_date, v_user);
    v_lines := v_lines + 1;
  END LOOP;
  INSERT INTO public.audit_log (tenant_id, actor_user_id, actor_role, action, entity, entity_id, after)
    VALUES (v_tenant, v_user, v_role, 'supplier_return.apply_credit', 'supplier_return', v_doc.id,
      jsonb_build_object('number', v_doc.number, 'supplier', v_supplier, 'date', p_date, 'amount', v_total::text, 'bills', v_lines, 'left', (v_left - v_total)::text));
  RETURN v_lines;
END $$;
